dataKeys.postFuncBody:
// If this is the very first historical point, start at 0
if (prevValue === undefined || prevValue === null || timePrev === null) {
    return 0;
}

// 1. Time difference in hours between this historical point and the previous one
var hoursElapsed = (time - timePrev) / (1000 * 60 * 60);

// 2. Average kilowatts during this interval
var kW = value / 1000;

// 3. Add this interval's energy (kWh = kW * hours) to the running historical total
return Number((prevValue + (kW * hoursElapsed)).toFixed(2));

dateColor.colorFunction:
var temperature = value;
if (typeof temperature !== undefined) {
  var percent = (temperature + 60)/120 * 100;
  return tinycolor.mix('blue', 'red', percent).toHexString();
}
return 'blue';
